  //#region src/methods/effect.d.ts
  interface Effect<State> extends Computed<State> {
    unsubscribe: Unsubscribe;
  }
  /**
   * Creates a reactive side effect that automatically tracks dependencies and
   * cleans itself up.
   *
   * \`effect\` is similar to \`computed\` but designed for running side effects. It
   * automatically subscribes to any atoms read within the callback (\`cb\`). When
   * the effect's reactive context is aborted (e.g., component unmount in
   * \`reatomFactoryComponent\`, cancellation in \`withAbort\` / \`withAsyncData\`), the
   * effect's execution is stopped, and any ongoing async operations within it
   * (like \`await wrap(sleep(...))\`) are cancelled.
   *
   * @example
   *   import { atom, effect, wrap, sleep, isAbort } from '@reatom/core'
   *
   *   const isActive = atom(true, 'isActive')
   *   const data = atom(0, 'data')
   *
   *   // This effect polls data every 5 seconds while isActive is true
   *   const polling = effect(async () => {
   *     if (!isActive()) return // Depends on isActive
   *
   *     console.log('Polling started...')
   *     while (true) {
   *       const fetchedData = await wrap(fetch('/api/poll'))
   *       const jsonData = await wrap(fetchedData.json())
   *       data(jsonData.value)
   *       await wrap(sleep(5000)) // Abortable sleep == debounce
   *     }
   *   }, 'pollingEffect')
   *
   *   // To manually stop:
   *   // polling.unsubscribe()
   *
   * @param cb The function to run as a side effect. It can be async. Any atoms
   *   read inside \`cb\` will become dependencies.
   * @param name Optional name for debugging purposes. Auto-generated if not
   *   provided.
   * @returns The new computed atom with \`unsubscribe\` method to manually clean up
   *   the effect. Calling this function is usually not necessary when \`effect\` is
   *   used within managed contexts like \`reatomFactoryComponent\` or
   *   \`withConnectHook\`, as cleanup happens automatically.
   */
  let effect: <T>(cb: () => T, name?: string) => Computed<T | undefined> & AbortExt & DynamicSubscriptionExt & {
    unsubscribe: Unsubscribe;
  };
  //#endregion
  //#region src/methods/framePromise.d.ts
  /**
   * Request the result of the current atom or action function as a promise.
   *
   * Returns a promise that resolves to the current execution frame's state
   * (action payload or atom state). Use it to catch errors from subsequent
   * operations in a cleaner way than traditional try-catch. Use \`finally\` to
   * clean up resources and so on. This method respects wrap and abortVar
   * policies.
   *
   * Inspired by TC39 explicit resource management proposal, but simpler and
   * coupled to Reatom's async stack for an ergonomic usage.
   *
   * @example
   *   export const processPayment = action(async (orderId: string) => {
   *     framePromise().catch((error) => showErrorNotification(error))
   *
   *     let order = await wrap(fetchOrder(orderId))
   *     await wrap(validateInventory(order))
   *     await wrap(chargeCustomer(order))
   *     await wrap(updateOrderStatus(order, 'completed'))
   *
   *     return order
   *   })
   *
   * @example
   *   // Classic approach - boilerplate with try-catch
   *   export const doSome = action(async () => {
   *     try {
   *       await wrap(fetchUser())
   *       await wrap(updateProfile())
   *       await wrap(syncData())
   *     } catch (error) {
   *       toast(error)
   *     }
   *   })
   *
   *   // native using - no try-catch and no "finally" logic
   *   // only resource management with extra variables
   *   // you can adapt \`toast\`, but without the payload / error data
   *   export const doSome = action(async () => {
   *     using _ = toast
   *     await wrap(fetchUser())
   *     await wrap(updateProfile())
   *     await wrap(syncData())
   *   })
   *
   *   // With our framePromise() - clean and declarative
   *   export const doSome = action(async () => {
   *     framePromise().catch((error) => toast(error))
   *     await wrap(fetchUser())
   *     await wrap(updateProfile())
   *     await wrap(syncData())
   *   })
   *
   * @example
   *   // Native using works only within the current function scope=*
   *   export const processOrder = action(async (orderId: string) => {
   *     withErrorLogging() // Impossible with native using
   *     await wrap(fetchOrder(orderId))
   *   })
   *
   *   // But framePromise works with the current action/atom frame!
   *   // Helper functions can use parent's framePromise - powerful composition!
   *   let withErrorLogging = () => {
   *     framePromise().catch((error) => logger.error(error))
   *   }
   *   export const processOrder = action(async (orderId: string) => {
   *     withErrorLogging() // Helper uses the SAME action frame!
   *     await wrap(fetchOrder(orderId))
   *   })
   *
   * @returns Promise that resolves with the current frame's state
   * @see {@link https://github.com/tc39/proposal-explicit-resource-management}
   */
  let framePromise: () => Promise<unknown>;
  //#endregion
