  //#region src/methods/ifChanged.d.ts
  let isChanged: (target: AtomLike) => boolean;
  /**
   * Executes a callback when an atom's state changes
   *
   * This utility evaluates if an atom's state has changed during the current
   * frame execution and calls the provided callback with the new state (and
   * optionally the previous state if available).
   *
   * @example
   *   // Log when the user's name changes
   *   ifChanged(userName, (newName, oldName) => {
   *     console.log(\`Name changed from \${oldName} to \${newName}\`)
   *   })
   *
   * @template T - Type extending AtomLike
   * @param {T} target - The atom to monitor for changes
   * @param {(newState: AtomState<T>, oldState?: AtomState<T>) => void} cb -
   *   Callback to execute when the atom changes
   * @throws {ReatomError} If target is not a reactive atom
   */
  const ifChanged: <T extends AtomLike>(target: T, cb: (newState: AtomState<T>, oldState?: AtomState<T>, isFirst?: boolean) => void) => void;
  /**
   * Retrieves new action calls that occurred in the current batch.
   *
   * This utility function tracks action invocations and returns an array of new
   * calls that have been made during the current batch. It's particularly useful
   * for monitoring action activity within computed atoms or effects without
   * triggering side effects during the action execution itself.
   *
   * In a computed atom, the function compares the current action state with the
   * previous frame's state to determine which calls are new. If this is the first
   * time the action is being tracked, all current calls are considered new.
   * Otherwise, only calls that weren't present in the previous frame are
   * returned. If the computed triggered by some other dependent atom change, the
   * function may return an empty array. The past calls are not stored!
   *
   * @example
   *   // Monitor API calls in an effect
   *   const apiCall = action((endpoint: string) => fetch(endpoint), 'apiCall')
   *
   *   effect(() => {
   *     const newCalls = getCalls(apiCall)
   *     newCalls.forEach(({ payload, params }) => {
   *       console.log(\`API called: \${params[0]}, Response:\`, payload)
   *     })
   *   }, 'apiMonitor')
   *
   * @template Params - Array type representing the action's parameter types
   * @template Payload - Type of the action's return value/payload
   * @param {Action<Params, Payload>} target - The action to monitor for new calls
   * @returns {{ payload: Payload; params: Params }[]} Array of new action calls,
   *   each containing the action's payload (return value) and the parameters it
   *   was called with
   * @throws {ReatomError} If target is a reactive atom instead of an action
   */
  const getCalls: <Params extends any[], Payload>(target: Action<Params, Payload>) => Array<{
    payload: Payload;
    params: Params;
  }>;
  //#endregion
  //#region src/methods/isCausedBy.d.ts
  /**
   * Determines if an atom is part of the causal chain leading to the current
   * computation
   *
   * This recursive function checks if the given atom has caused the current
   * computation by traversing the computation tree. It's useful for determining
   * dependencies and understanding the flow of state changes through your
   * application.
   *
   * @example
   *   // Check if user atom changes caused the current computation
   *   if (isCausedBy(userAtom)) {
   *     console.log('This computation was triggered by user state change')
   *   }
   *
   * @param {AtomLike} target - The atom to check if it's part of the causal chain
   * @param {number} [depth=Infinity] - The depth of the causal chain to check.
   *   Default is \`Infinity\`
   * @param {Frame} [frame=top()] - The frame to check (defaults to the current
   *   top frame). Default is \`top()\`
   * @returns {boolean} True if the target atom is part of the causal chain, false
   *   otherwise
   */
  let isCausedBy: (target: AtomLike, depth?: number, frame?: Frame<any, any[], any>, visited?: Set<Frame<any, any[], any>>) => boolean;
  //#endregion
  //#region src/methods/memo.d.ts
  /**
   * Internal utility for keyed memoization within an atom's execution context.
   *
   * Caches values by key within the current atom frame, creating the value on
   * first access and returning the cached value on subsequent calls. This enables
   * persistent memoization across multiple invocations of the same atom.
   *
   * The cache is scoped per-atom and persists across all calls to that atom
   * within the same context, making it suitable for creating internal computed
   * atoms or other resources that should be created once and reused.
   *
   * @example
   *   // TODO cache
   *
   * @template T The type of value being cached
   * @param key Unique identifier for the cached value within the atom
   * @param create Factory function to create the value if not already cached
   * @returns The cached value, either newly created or retrieved from cache
   */
  let memoKey: <T>(key: string, create: () => T) => T;
  /**
   * Type representing the source of a function as a string. Used for caching and
   * identification purposes.
   */
  type FunctionSource = string;
  /**
   * Memoize additional computation inside a different calls of an atom (computed
   * or an effect) or an action.
   *
   * It's useful when you want to avoid recomputing of the whole computed
   * function, especially if the computation is expensive. You could create an
   * external atom by yourself, but it is not handy sometimes.
   *
   * The \`memo\` function takes a callback function \`cb\` that returns the value to
   * be memoized, an optional \`equal\` function that compares the new and old
   * values to determine if the memoized value should be updated, and an optional
   * \`key\` to uniquely identify the memoized value.
   *
   * **Important note**: The created internal atom only uses the first passed
   * callback function. This means it's unsafe to rely on data from the closure
   * that changes on every recall, as subsequent calls will not update the
   * callback used by the internal atom.
   *
   * Note for rare cases: A created underhood atom is memorized for each memo by
   * the passed function sources from "toString()" method, so every computed
   * callback in different memos of the same atom should contain different code.
   * However, you can provide a custom \`key\` parameter to uniquely identify
   * different memo calls instead of relying on toString().
   *
   * When a custom \`key\` is provided, the toString() duplication check is
   * bypassed, allowing you to use the same callback function multiple times
   * within the same atom by providing different keys for each usage.
   *
   * @example
   *   // This is very useful to memoize not just the end string,
   *   // but, for example, a template computation inside \`reatomComponent\` or so on.
   *   export const listSum = computed(() => {
   *     // Simple call of \`list().length\` will cause extra recomputations for elements sorting or its internal changes.
   *     // correct optimal way, the component will rerender only on \`length\` change
   *     const length = memo(() => list().length)
   *     // you could call different \`memo\` many times in one computed
   *     const sum = memo(() => list().reduce((acc, el) => acc + el().value, 0))
   *
   *     return \`The sum of \${length} elements is: \${sum}\`
   *   }, 'listSum')
   *
   * @example
   *   // An example of using the equality function as part of the logic
   *   const scroll = atom(0, 'scroll')
   *   const throttledScroll = computed(() => {
   *     const { state } = memo(
   *       () => ({ state: scroll(), time: Date.now() }),
   *       // Only update if 50ms have passed since the last update
   *       (next, prev) => prev.time + 50 < Date.now(),
   *     )
   *     return state
   *   }, 'throttledScroll')
   *
   * @example
   *   // Using memo in actions for expensive computations
   *   const processData = action((data: string[]) => {
   *     // You can even create a service, but not one that is tied only to this action.
   *     const myService = memo(() => new Service())
   *
   *     myService.send(data)
   *   }, 'processData')
   *
   * @param cb A function that returns the value to be selected and memoized.
   * @param {function(State, State): boolean} [Object.is] An optional function to
   *   compare the new and old states, useful for reactive context. If the memo
   *   appears in reactive context (\`computed\`, \`effect\`) then before triggering
   *   the host recomputation the returned value compares with the previous
   *   returned value. This option defines the comparator algorithm. By default it
   *   is a simple reference comparison (\`Object.is\`).
   * @param key An optional unique identifier for the memoized value. Defaults to
   *   \`cb.toString()\`. Used to distinguish between different memo calls within
   *   the same computed function. Providing a custom key is recommended when
   *   using similar callback functions to avoid conflicts.
   * @returns The memoized value.
   */
  let memo: <State>(cb: (() => State) | ((state?: State) => State), equal?: (newState: State, oldState: State) => boolean, key?: string) => State;
  //#endregion
  //#region src/methods/peek.d.ts
  /**
   * Executes a callback in the current context without reactive bindings
   * (dependencies tracking)
   *
   * @example
   *   // reset paging on search changes
   *   effect(() => {
   *     const searchState = search()
   *
   *     // get page state without subscribing to it!
   *     if (peek(page) > 1) peek(0)
   *   })
   *
   * @example
   *   const query = atom('', 'query')
   *   const someResource = computed(
   *     async () => api.getSome(query()),
   *     'someResource',
   *   ).extend(withAsyncData())
   *
   *   const tip = computed(() => {
   *     if (!someResource.ready()) {
   *       return 'Searching...'
   *     }
   *
   *     const list = someResource.data()
   *
   *     if (list.length === 0) {
   *       // no need to subscribe to the query changes!
   *       return peek(query) ? 'Nothing found' : 'Try to search something'
   *     }
   *
   *     return \`Found \${list.length} elements\`
   *   })
   */
  let peek: <Params extends any[], Result>(cb: (...params: Params) => Result, ...params: Params) => Result;
  //#endregion
  //#region src/methods/reatomLens.d.ts
  type LensKey = string | number | symbol;
  type ResolveLensKey<Key> = Key extends Atom<infer K> ? K : Key;
  type LensValue<T, K extends LensKey> = T extends Map<infer MapKey, infer MapValue> ? K extends MapKey ? MapValue | undefined : never : T extends ReadonlyArray<infer V> ? K extends number ? V | undefined : never : K extends keyof T ? T[K] : never;
  /**
   * Creates a lens atom that provides focused access to a nested property within
   * a parent atom's state.
   *
   * A lens atom automatically tracks changes in the parent atom and provides
   * immutable updates back to the parent when modified. It supports objects,
   * arrays, and Maps.
   *
   * @example
   *   // With an object
   *   const userAtom = atom({ name: 'John', age: 30 })
   *   const nameAtom = reatomLens(userAtom, 'name')
   *   nameAtom() // → 'John'
   *   nameAtom.set('Jane') // Updates userAtom to { name: 'Jane', age: 30 }
   *
   * @example
   *   // With an array
   *   const listAtom = atom(['a', 'b', 'c'])
   *   const firstAtom = reatomLens(listAtom, 0)
   *   firstAtom() // → 'a'
   *   firstAtom.set('x') // Updates listAtom to ['x', 'b', 'c']
   *
   * @example
   *   // With a Map
   *   const mapAtom = atom(new Map([['key1', 'value1']]))
   *   const valueAtom = reatomLens(mapAtom, 'key1')
   *   valueAtom() // → 'value1'
   *   valueAtom.set('value2') // Updates mapAtom with new Map
   *
   * @example
   *   // With a dynamic atom key
   *   const dataAtom = atom({ name: 'John', age: 30 })
   *   const fieldAtom = atom<'name' | 'age'>('name')
   *   const valueAtom = reatomLens(dataAtom, fieldAtom)
   *   valueAtom() // → 'John'
   *   fieldAtom.set('age')
   *   valueAtom() // → 30
   *
   * @example
   *   // With custom get/set functions
   *   const dataAtom = atom({ nested: { deep: { value: 42 } } })
   *   const deepAtom = reatomLens(dataAtom, 'nested', {
   *     get: (parent) => parent.nested?.deep?.value,
   *     set: (parent, _, value) => ({
   *       ...parent,
   *       nested: {
   *         ...parent.nested,
   *         deep: { ...parent.nested.deep, value },
   *       },
   *     }),
   *   })
   *
   * @template Parent - The type of the parent atom
   * @template Key - The key type to access the nested property
   * @param parent - The parent atom containing the state to lens into
   * @param key - The key to access the nested property (string for objects,
   *   number for arrays, any for Maps) or an atom with the key state
   * @param options - Optional configuration with custom get/set functions
   * @param options.get - Custom function to extract the value from the parent
   *   state. Defaults to parent[key] for objects/arrays or parent.get(key) for
   *   Maps
   * @param options.set - Custom function to immutably update the parent state.
   *   Defaults to creating new objects/arrays/Maps with the updated value
   * @param name - Optional name for the lens atom. Defaults to
   *   \`\${parent.name}.\${key}\` where atom keys use the key atom name
   * @returns A lens atom that tracks and updates the parent atom's nested
   *   property
   */
  const reatomLens: <Parent extends Atom<any>, Key extends LensKey | Atom<LensKey>, ResolvedKey extends ResolveLensKey<Key> & LensKey = ResolveLensKey<Key> & LensKey, Value = LensValue<AtomState<Parent>, ResolvedKey>>(parent: Parent, key: Key, options?: {
    get?: (parent: AtomState<Parent>, key: ResolvedKey) => Value;
    set?: (parent: AtomState<Parent>, key: ResolvedKey, value: Value) => AtomState<Parent>;
  }, name?: string) => Atom<Value>;
  //#endregion
  //#region src/methods/reatomObservable.d.ts
  interface ProducerObject<T> {
    initState?: T;
    getState?: () => T;
    next?: (state: T) => void;
    subscribe?: (fn: (state: T) => void) => MaybeUnsubscribe;
  }
  type Producer<T> = ProducerObject<T> | ((trigger: Fn) => ProducerObject<T>);
  /**
   * Extends an existing atom to synchronize with an observable-like data source.
   *
   * @template Target - The type of the atom being extended
   * @param _producer - Either an object with optional \`initState\`, \`getState\`,
   *   \`next\`, and \`subscribe\` fields, or a function that receives a \`trigger\`
   *   callback and returns such an object.
   * @returns An extension function that adds observable synchronization to an
   *   atom
   */
