  type AsyncStatus<State = never, InitState = State, Err = Error> = AsyncStatusNeverPending<State, InitState, Err> | AsyncStatusFirstAborted<State, InitState, Err> | AsyncStatusPending<State, InitState, Err> | AsyncStatusFulfilled<State, InitState, Err> | AsyncStatusRejected<State, InitState, Err> | AsyncStatusAbortedSettle<State, InitState, Err>;
